from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=g[0][0] and not seen[r][c]:
                q=[(r,c)]; seen[r][c]=True; pile=[]
                while q:
                    y,x=q.pop(); pile.append((y,x,g[y][x]))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]!=g[0][0]:
                            seen[ny][nx]=True; q.append((ny,nx))
                out.append(pile)
    return out
