    sy,sx=(obj[0][0]+obj[-1][0])//2,(obj[0][1]+obj[-1][1])//2
    # collect object cells as offsets from center
    offs=[(y-sy,x-sx,g[y][x]) for y,x,_ in obj]
    o=[row[:] for row in g]
    for py,px,v in seeds:
        for dy,dx,val in offs:
            y,x=py+dy,px+dx
            if 0<=y<len(o) and 0<=x<len(o[0]): o[y][x]=val
